function classifyWaterD4(map){const waters=(map?.tiles||[]).filter(t=>t.terrain==='water');if(!waters.length)return;const seen=new Set();for(const start of waters){if(seen.has(start.id))continue;const comp=[],q=[start.id];seen.add(start.id);let edge=false;while(q.length){const id=q.shift(),t=map.get(id);if(!t)continue;comp.push(id);if(t.x===0||t.y===0||t.x===map.width-1||t.y===map.height-1)edge=true;for(const n of map.neighbors4(id))if(n.terrain==='water'&&!seen.has(n.id)){seen.add(n.id);q.push(n.id);}}if(!edge){for(const id of comp)map.get(id).waterType='lake';continue;}const set=new Set(comp),dist=new Map(),qq=[];for(const id of comp){const t=map.get(id);if(map.neighbors4(id).some(n=>n.terrain!=='water')){dist.set(id,1);qq.push(id);}}for(let i=0;i<qq.length;i++){const id=qq[i],d=dist.get(id);for(const n of map.neighbors4(id))if(set.has(n.id)&&!dist.has(n.id)){dist.set(n.id,d+1);qq.push(n.id);}}for(const id of comp){const d=dist.get(id);map.get(id).waterType=!Number.isFinite(d)?'unclassified':d<=1?'coast':d<=2?'sea':'ocean';}}}
