function spaceDiagD4(v,t){const used=Number(NS.V017?.usedSpace?.(t)||0),dev=Number(t?.developedBuildSpace||0),tech=Number(NS.V017?.accessiblePotential?.(v,t)||dev),final=finalLimitD4(t);return{used,dev,tech,final,remaining:Math.max(0,dev-used),undeveloped:Math.max(0,tech-dev)};}
function housingDiagHTMLD4(v,w,t){const s=spaceDiagD4(v,t),rows=NS.V032D3?.housingRows?.(v,w)||[],r=rows.find(x=>Number(x.id)===Number(t.id)),block=ensureD4(v).housingBlocker,cap=Number(r?.cap||0),pop=Number(r?.pop||0),free=Math.max(0,cap-pop);return`<div class="v32d4-space"><strong>🏗️ D4 건축공간·주거 진단</strong><div class="v32d4-spacegrid"><span>사용 <b>${s.used.toFixed(1)}</b></span><span>개발됨 <b>${s.dev.toFixed(1)}</b></span><span>현재 기술상한 <b>${s.tech.toFixed(1)}</b></span><span>지형 최종한계 <b>${s.final.toFixed(1)}</b></span><span>즉시 남은 공간 <b>${s.remaining.toFixed(1)}</b></span><span>추가 정비 가능 <b>${s.undeveloped.toFixed(1)}</b></span></div><div class="small">주민 ${pop}명 · 주거 수용 ${cap.toFixed(1)} · 빈 주거 ${free.toFixed(1)} · 점유 ${cap>0?(pop/cap*100).toFixed(0):'0'}%</div><div class="small muted">국가 주거 해결 blocker <b>${block}</b>${v.hasTech?.('URBAN_REDEVELOPMENT')?' · 도시 정비 적용':' · 도시 정비 미연구'}</div></div>`;}

/* ---------- telemetry ---------- */
const snapD3=NS.Telemetry.prototype.snapshot;
NS.Telemetry.prototype.snapshot=function(w,reason='AUTO',note=''){const s=snapD3.call(this,w,reason,note);if(!s)return s;const wa=auditWaterD4(w);let executed=0,vol=0,tre=0,net=0;for(const row of s.villages||[]){const v=(NS.V035H1B1?.lookupVillage?.(w,row.id)??w.villages.find(x=>Number(x.id)===Number(row.id)));if(!v)continue;const st=updateStructuralD4(v,w),f=st.tradeFunnel,counts=f.counts||{},top=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0]?.[0]||'NONE';Object.assign(row,{housingBlocker32D4:st.housingBlocker,structuralWoodDemand32D4:Number(st.structuralDemand?.wood?.severity||0),structuralStoneDemand32D4:Number(st.structuralDemand?.stone?.severity||0),tradeExecuted32D4:Number(f.executed||0),tradeVolume32D4:+Number(f.volume||0).toFixed(2),tradeTopBlocker32D4:top,tradeNoRoute32D4:Number(counts.NO_ROUTE||0),tradeNoDemand32D4:Number(counts.NO_DEMAND||0),tradeNoSurplus32D4:Number(counts.NO_SURPLUS||0),tradePriceBlock32D4:Number(counts.PRICE||0),tradeStrategicPriceBlock32D4:Number(counts.STRATEGIC_PREMIUM||0),tradeBudgetBlock32D4:Number(counts.BUDGET||0),treasuryTradeSupport32D4:+Number(st.treasuryTradeSupport||0).toFixed(2),marketNetworkTransfers32D4:+Number(st.marketNetworkTransfers||0).toFixed(2)});executed+=Number(f.executed||0);vol+=Number(f.volume||0);tre+=Number(st.treasuryTradeSupport||0);net+=Number(st.marketNetworkTransfers||0);}Object.assign(s.global,{tradeExecuted32D4:executed,tradeVolume32D4:+vol.toFixed(2),treasuryTradeSupport32D4:+tre.toFixed(2),marketNetworkTransfers32D4:+net.toFixed(2),waterLake32D4:wa.lake,waterCoast32D4:wa.coast,waterSea32D4:wa.sea,waterOcean32D4:wa.ocean,waterUnclassified32D4:wa.unclassified});const ys=(this.yearlySummaries||[]).find(x=>Number(x.year)===Number(w.year));if(ys){Object.assign(ys.global,s.global);for(const n of ys.nations||[]){const r=s.villages.find(x=>Number(x.id)===Number(n.id));if(r)Object.assign(n,r);}}return s;};
const csvD3=NS.Telemetry.prototype.snapshotsCSV;
NS.Telemetry.prototype.snapshotsCSV=function(){const base=csvD3.call(this),lines=base.split('\n');if(!lines.length)return base;const extra=['housingBlocker32D4','structuralWoodDemand32D4','structuralStoneDemand32D4','tradeExecuted32D4','tradeVolume32D4','tradeTopBlocker32D4','tradeNoRoute32D4','tradeNoDemand32D4','tradeNoSurplus32D4','tradePriceBlock32D4','tradeStrategicPriceBlock32D4','tradeBudgetBlock32D4','treasuryTradeSupport32D4','marketNetworkTransfers32D4'],esc=v=>`"${String(v??'').replace(/"/g,'""')}"`;lines[0]+=','+extra.map(esc).join(',');let i=1;for(const s of this.snapshots||[])for(const v of s.villages||[]){if(i>=lines.length)break;lines[i++]+=','+extra.map(k=>esc(v[k]??s.global?.[k])).join(',');}return lines.join('\n');};
const jsonD3=NS.Telemetry.prototype.toJSON;
NS.Telemetry.prototype.toJSON=function(w){const d=jsonD3.call(this,w);d.version='0.32D4';Object.assign(d.worldSummary,{v32D4Revision:REV32D4,buildSpaceV2:'base terrain build space buff + URBAN_REDEVELOPMENT hard-cap expansion; settlement UI separates used/developed/current-tech/final terrain limit',internationalPriceV2:'seller quote = local price + repeat-demand premium + strategic premium + relation adjustment - cash-pressure discount; buyer willingness rises with structural urgency',tradeFinance32D4:'normal and industrial international trade settle Market Gold -> Market Gold; domestic market liquidity bridges first, Treasury support only for urgent procurement',tradeFunnel32D4:'NO_ROUTE/NO_DEMAND/NO_SURPLUS/PRICE/STRATEGIC_PREMIUM/BUDGET/MIN_QTY/STORAGE aggregated by nation',waterAudit32D4:w.v32d4WaterAudit||auditWaterD4(w),housingReserveLog32D4:'per-attempt D3 reserve-block detail suppressed; 30-day aggregate summaries only',performance32D4:'D3 housing rows, life-zone/admin-region lookups and V29 internal route costs cached by short simulation buckets; reserve-log detail compressed'});return d;};

