const villageSerD3=NS.Village.prototype.serialize;
NS.Village.prototype.serialize=function(){const d=villageSerD3.call(this);d.v32d4=JSON.parse(JSON.stringify(ensureD4(this)));return d;};
const worldSerD3=NS.World.prototype.serialize,worldFromD3=NS.World.from;
NS.World.prototype.serialize=function(){const d=worldSerD3.call(this);d.version='0.32D4';d.v32d4={revision:REV32D4,tradeMemory:this.v32d4TradeMemory||{},waterAudit:this.v32d4WaterAudit||null,marketGoldInternational:true,urbanRedevelopment:true,combat:false};return d;};
function attachD4(w,src=null){w=NS.V032D3?.attachWorld?.(w)||w;if(!w)return w;w.v32d4TradeMemory=src?.v32d4?.tradeMemory||w.v32d4TradeMemory||{};for(const v of w.villages||[]){v._world=w;const old=src?.villages?.find?.(x=>Number(x.id)===Number(v.id))?.v32d4;if(old)v.v32d4=old;ensureD4(v);updateStructuralD4(v,w);}auditWaterD4(w);return w;}
NS.World.from=function(d){if(d?.version==='0.32D4'){const w=worldFromD3({...d,version:'0.32D3'});return attachD4(w,d);}return attachD4(worldFromD3(d));};

