 NS.UI.prototype.renderTile=function(){tileD3.call(this);const t=this.world.map.get(this.world.selectedTileId),root=this.q('tileInspector');if(!t||!root)return;if(t.terrain==='water'){const lab={lake:'호수',coast:'연안',sea:'해양',ocean:'대양'}[t.waterType]||'미분류 수역';root.innerHTML=`<strong>(${t.x},${t.y}) 🌊 ${lab}</strong><br><span class="small muted">D4 수역 재분류 · 호수/연안/해양/대양을 명시적으로 구분합니다.</span>`;return;}if(t.ownerId!=null){const v=this.world.villages[t.ownerId];updateStructuralD4(v,this.world);root.insertAdjacentHTML('beforeend',housingDiagHTMLD4(v,this.world,t));}};
 NS.UI.prototype.renderVillageContent=function(){contentD3.call(this);const v=this.world.selectedNation,root=this.q('villageContent');if(!v||!root)return;const st=updateStructuralD4(v,this.world);if(this.sub==='settlements'){const id=Number(this.selectedSettlementDetailId??this.world.selectedTileId),t=v.territory.has(id)?this.world.map.get(id):null,detail=root.querySelector('.v17-settlement-detail');if(t&&detail&&!detail.querySelector('.v32d4-space'))detail.insertAdjacentHTML('beforeend',housingDiagHTMLD4(v,this.world,t));}if(this.sub==='trade'){const f=st.tradeFunnel,top=Object.entries(f.counts||{}).sort((a,b)=>b[1]-a[1])[0];root.insertAdjacentHTML('afterbegin',`<div class="v32d4-trade"><strong>🌐 D4 국제가격·시장결제</strong><div class="small">Market→Market 결제 · 국가간 거래 ${f.executed}회 / ${Number(f.volume||0).toFixed(1)} 단위 · 국고 긴급지원 ${Number(st.treasuryTradeSupport||0).toFixed(1)}G</div><div class="small muted">구조수요 🪵 ${Number(st.structuralDemand?.wood?.severity||0).toFixed(2)} · 🪨 ${Number(st.structuralDemand?.stone?.severity||0).toFixed(2)} · 주거 blocker ${st.housingBlocker} · 최다 거래탈락 ${top?`${top[0]} ${top[1]}회`:'없음'}</div>${st.lastTradeQuote?`<div class="small muted">최근 제시: ${st.lastTradeQuote.seller} ${RLAB[st.lastTradeQuote.resource]||st.lastTradeQuote.resource} ${st.lastTradeQuote.unit.toFixed(3)}G + 운송 → ${st.lastTradeQuote.landed.toFixed(3)}G · 지불의사 ${st.lastTradeQuote.wtp.toFixed(3)}G</div>`:''}</div>`);}if(this.sub==='economy')root.insertAdjacentHTML('beforeend',`<div class="v32d4-trade"><strong>🏦 D4 구조적 조달</strong><div class="small">주거 blocker <b>${st.housingBlocker}</b> · 목재 수입압력 ${Number(st.structuralDemand?.wood?.severity||0).toFixed(2)} · 석재 수입압력 ${Number(st.structuralDemand?.stone?.severity||0).toFixed(2)}</div><div class="small muted">정상 국제교역은 Settlement Market Gold를 우선 사용하고, 긴급 구조수요에서만 Treasury가 시장에 보조합니다.</div></div>`);};
