if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.32D4'))NS.PATCH_NOTES.unshift({version:'V0.32D4',date:'2026-09-26',title:'후기 도시·시장·성능 안정화',summary:'D3 100년 장기주행에서 드러난 티아형 주거/석재 교착, 국제교역 정지, 수역 분류 오류와 후기 성능 비용을 함께 정리합니다.',sections:[['건축공간 V2',['지형별 기본/최대 건축공간을 소폭 상향하고 후기 기술 「도시 정비」를 추가해 기존 지형 hard cap을 확장합니다.','정착지 상세에 사용/개발됨/현재 기술상한/지형 최종한계/남은 공간을 분리 표시하고 주거 수용·점유·blocker를 함께 보여줍니다.']],['주거·구조수요',['D3의 실제 빈 주거 이동→고밀도 개축→타 정착지 주택→토지정비 순서를 유지하고, 장기 주거/확장 blocker가 목재·석재 구조적 수입수요로 연결됩니다.','주거 reserve 차단 로그는 개별 타일 이벤트를 저장하지 않고 30일 집계로 압축합니다.']],['국제가격 V2',['일반자원과 산업자원 국제교역을 Settlement Market Gold→Settlement Market Gold 결제로 통일합니다. 다른 국내 시장 유동성을 먼저 모으고 구조적 긴급수요에서만 Treasury가 보조합니다.','판매가는 반복구매·전략적 경계·관계·판매자의 현금압박을 반영하고 구매자의 구조적 긴급도는 최대 지불가격을 높입니다. 관계도 -35 단순 금지 대신 조건·가격 악화로 표현합니다.','Trade Funnel에서 NO_ROUTE/NO_DEMAND/NO_SURPLUS/PRICE/STRATEGIC_PREMIUM/BUDGET 등을 집계합니다.']],['수역·성능',['미분류 수역을 연안으로 표시하던 fallback을 제거하고 19×19에 맞게 연안/해양/대양 깊이 기준을 재조정합니다.','D3 주거행·생활권·행정권 계산을 날짜/주민 epoch 기준으로 캐시해 후기 반복 순회를 줄입니다.']]]});
(function(){const KEY='village-observer-v0-32d4',fallback=['village-observer-v0-32d3','village-observer-v0-32d2','village-observer-v0-32d1','village-observer-v0-32d','village-observer-v0-32c2','village-observer-v0-32c1a','village-observer-v0-32c1','village-observer-v0-32b','village-observer-v0-32a','village-observer-v0-31i','village-observer-v0-31h','village-observer-v0-31g','village-observer-v0-31f'];function dl(name,text,type='application/json'){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}NS.SaveSystem={save(w){localStorage.setItem(KEY,JSON.stringify(w.serialize()));},load(){let r=localStorage.getItem(KEY);for(const k of fallback)if(!r)r=localStorage.getItem(k);return r?NS.World.from(JSON.parse(r)):null;},export(w){dl(`village-observer-v032D4-save-${w.year}y.json`,JSON.stringify(w.serialize()));},exportDevJSON(w){dl(`village-observer-v032D4-devlog-${w.telemetry.sessionId}.json`,JSON.stringify(w.telemetry.toJSON(w)));},exportDevCSV(w){dl(`village-observer-v032D4-snapshots-${w.telemetry.sessionId}.csv`,'﻿'+w.telemetry.snapshotsCSV(),'text/csv;charset=utf-8');},async import(file){return NS.World.from(JSON.parse(await file.text()));},async importMap(file){return attachD4(NS.V019.worldFromMapData(JSON.parse(await file.text())));}};})();
